from math import exp
from itertools import product
s=lambda x:1/(1+exp(-x))
joint={}
for h,v,c,r,y in product((0,1),repeat=5):
    phv=1/6 if h==v else 1/3
    pr=s(.75*h+.5*c)
    py=s(-.5+2.5*v+1.75*c)
    joint[h,v,c,r,y]=phv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def conditional_y(**conditions):
    indices={'h':0,'v':1,'c':2,'r':3}
    subset={k:p for k,p in joint.items() if all(k[indices[a]]==b for a,b in conditions.items())}
    return sum(p for k,p in subset.items() if k[4]==1)/sum(subset.values())
print('Exact probabilities under the stated simulation SCM:')
print('P(Y=1|H=0)=',conditional_y(h=0))
print('P(Y=1|H=1)=',conditional_y(h=1))
for c in (0,1):
    for r in (0,1):
        print(f'P(Y=1|C={c},R={r})=',conditional_y(c=c,r=r))
print('Label prevalence=',conditional_y())
print('Bayes accuracy from V,C=',sum(max(s(-.5+2.5*v+1.75*c),1-s(-.5+2.5*v+1.75*c)) for v,c in product((0,1),repeat=2))/4)
print('Reported bird split sum=',2849+520+529)
print('Maximum nominal cells for 5-level feature, 9 labels, four 5-level conditioning variables=',5*9*5**4)
